<?php
declare(strict_types=1);
namespace OCP {interface IDBConnection {public function executeQuery(string $sql,array $params):object;}}
namespace OCA\Forms\Mcp\Service {
 class CircleReadData {public static function page(array $rows):array{return$rows;}}
 class CircleRuntime {public static function readShareIdentity(\OCA\Forms\Mcp\Service\CircleDetached\Lease $lease,\Closure $read):mixed{return$lease->metadataRead($read);}public static function readProviderParent(\OCA\Forms\Mcp\Service\CircleDetached\Lease $lease,\Closure $read):mixed{return$lease->metadataRead($read);}}
 class FreshCore {public function __construct(string $uid){}public function apps():self{return$this;}public function user():self{return$this;}public function isEnabledForUser(string $app,object $user):bool{return true;}}
 class CircleExistingIdentity {public static bool $changed=false;public static function read(object $db,string $uid):array{return['uid'=>self::$changed?'different':$uid];}}
 class CircleReadConfig {public static array $data=[];public static function read(object $db,array $system):array{return self::$data;}}
 class OriginReadAuthority {public static bool $active=false;public static function check():bool{return self::$active;}}
 class OriginContext {public static string $tool='forms_transfer';public static int $frames=0;public static function active():bool{return true;}public static function current():array{return['verified'=>['tool'=>self::$tool,'uid'=>'actor']];}public static function transferSharingAuthority():array{return['frame'=>static fn()=>null];}public static function verifiedRead(\Closure $frame,\Closure $read):mixed{self::$frames++;OriginReadAuthority::$active=true;try{return$read();}finally{OriginReadAuthority::$active=false;}}}
}
namespace OCA\Forms\Mcp\Service\CircleDetached {
 final class Reader {public function read(Lease $lease,\Closure $read):mixed{return$lease->readData($read);}}
 class ShareWrapperRequest {public function readModel(Lease $lease,\Closure $read):mixed{return$lease->metadataRead($read);}}
 class SourceGate {public int $frames=0;public int $checks=0;public bool $active=false;public function assert(string $uid):void{$this->checks++;}public function verifiedRead(string $uid,\Closure $read):mixed{if($this->active)throw new \RuntimeException('nested');$this->frames++;$this->active=true;try{return$read();}finally{$this->active=false;}}}
 final class ScopedFederatedUserService {public function getLocalFederatedUser(Lease $lease,\Closure $read):mixed{return$lease->metadataRead($read);}}
}
namespace {
require_once __DIR__.'/../src/Service/CircleDetached/Lease.php';
use OCA\Forms\Mcp\Service\{OriginContext,OriginReadAuthority,CircleDetached\Lease,CircleDetached\SourceGate,CircleDetached\ScopedFederatedUserService};
final class CircleMetadataSourceReadTest extends \PHPUnit\Framework\TestCase {
 private Lease $lease;private SourceGate $gate;private int $authority=0;private bool $revoked=false;
 protected function setUp():void{\OCA\Forms\Mcp\Service\CircleExistingIdentity::$changed=false;\OCA\Forms\Mcp\Service\CircleReadConfig::$data=[];OriginContext::$tool='forms_transfer';OriginContext::$frames=0;OriginReadAuthority::$active=false;$this->gate=new SourceGate();$this->lease=(new ReflectionClass(Lease::class))->newInstanceWithoutConstructor();$db=new class implements \OCP\IDBConnection {public function executeQuery(string $sql,array $params):object{return new class {public function fetchAll():array{return[];}public function closeCursor():void{}};}};foreach(['uid'=>'actor','connection'=>$db,'sources'=>$this->gate,'started'=>hrtime(true),'identity'=>['uid'=>'actor'],'configData'=>[],'keyhole'=>'0','readSystem'=>static fn()=>[],'assertAuthority'=>function():void{$this->authority++;if($this->revoked)throw new \RuntimeException('revoked');}]as$k=>$v)(new ReflectionProperty($this->lease,$k))->setValue($this->lease,$v);}
 private function read(\Closure $read):mixed{return(new ScopedFederatedUserService())->getLocalFederatedUser($this->lease,$read);}
 public function testClosedMetadataDefersOnlyDuplicateGuardAndKeepsEveryQueryCounted():void{$this->read(function():void{for($i=0;$i<3;$i++)$this->lease->checkpoint();});self::assertSame(2,$this->authority);self::assertSame(5,$this->gate->checks);self::assertSame(5,(new ReflectionProperty($this->lease,'queries'))->getValue($this->lease));}
 public function testClosedDtoUsesTheSameBoundedTransferRules():void{OriginReadAuthority::$active=true;self::assertSame(42,(new \OCA\Forms\Mcp\Service\CircleDetached\Reader())->read($this->lease,function():int{for($i=0;$i<3;$i++)$this->lease->checkpoint();return 42;}));self::assertSame(2,$this->authority);self::assertSame(5,$this->gate->checks);}
 public function testOtherToolsKeepPerQueryAuthorityChecks():void{OriginContext::$tool='forms_link_results_file';OriginReadAuthority::$active=true;(new \OCA\Forms\Mcp\Service\CircleDetached\Reader())->read($this->lease,function():int{for($i=0;$i<3;$i++)$this->lease->checkpoint();return 42;});self::assertSame(5,$this->authority);}
 public function testActorRevocationCannotPublishTheReadResult():void{$published=false;try{$this->read(function():int{$this->revoked=true;return 42;});$published=true;self::fail('Revoked read published');}catch(RuntimeException){}self::assertFalse($published);$this->lease->assertNoMetadataWrite();}
 public function testIncarnationChangeCannotPublishTheReadResult():void{$published=false;try{$this->read(static function():int{\OCA\Forms\Mcp\Service\CircleExistingIdentity::$changed=true;return 42;});$published=true;self::fail('Changed incarnation published');}catch(RuntimeException){}self::assertFalse($published);$this->lease->assertNoMetadataWrite();}
 public function testConfigChangeCannotPublishTheReadResult():void{$published=false;try{$this->read(static function():int{\OCA\Forms\Mcp\Service\CircleReadConfig::$data=['changed'=>true];return 42;});$published=true;self::fail('Changed configuration published');}catch(RuntimeException){}self::assertFalse($published);$this->lease->assertNoMetadataWrite();}
 public function testExpiredOriginFrameStopsAnInternalQuery():void{$this->expectException(RuntimeException::class);$this->read(function():void{OriginReadAuthority::$active=false;$this->lease->checkpoint();});}
 public function testClosedDtoCannotReachAWrite():void{OriginReadAuthority::$active=true;$this->expectException(RuntimeException::class);try{(new \OCA\Forms\Mcp\Service\CircleDetached\Reader())->read($this->lease,fn()=>$this->lease->assertNoMetadataWrite());}finally{$this->lease->assertNoMetadataWrite();}}
 public function testParentModelLookupUsesSourceAndWriteBarrier():void{\OCA\Forms\Mcp\Service\CircleRuntime::readProviderParent($this->lease,function():void{self::assertTrue($this->gate->active);$this->expectException(RuntimeException::class);$this->lease->assertNoMetadataWrite();});}
 public function testShareIdentityLookupUsesSourceAndWriteBarrier():void{\OCA\Forms\Mcp\Service\CircleRuntime::readShareIdentity($this->lease,function():void{self::assertTrue($this->gate->active);$denied=false;try{$this->lease->assertNoMetadataWrite();}catch(RuntimeException){$denied=true;}self::assertTrue($denied);});self::assertFalse($this->gate->active);}
 public function testChildModelLookupUsesSourceAndWriteBarrier():void{(new \OCA\Forms\Mcp\Service\CircleDetached\ShareWrapperRequest())->readModel($this->lease,function():void{self::assertTrue($this->gate->active);$this->expectException(RuntimeException::class);$this->lease->assertNoMetadataWrite();});}
 public function testMetadataUsesBothClosedSourceAndAuthorityFrames():void{self::assertSame(42,$this->read(function():int{self::assertTrue($this->gate->active);self::assertTrue(OriginReadAuthority::check());return 42;}));self::assertSame(1,$this->gate->frames);self::assertSame(1,OriginContext::$frames);self::assertSame(2,$this->authority);self::assertFalse($this->gate->active);}
 public function testExistingAuthorityFrameStillChecksCircleSources():void{OriginReadAuthority::$active=true;$this->read(function():void{self::assertTrue($this->gate->active);});self::assertSame(1,$this->gate->frames);self::assertSame(0,OriginContext::$frames);}
 public function testReadFailureClosesBothFrames():void{$this->expectException(LogicException::class);try{$this->read(static function():never{throw new LogicException();});}finally{self::assertFalse($this->gate->active);self::assertFalse(OriginReadAuthority::check());$this->lease->assertNoMetadataWrite();}}
 public function testMetadataStillCannotReachWrite():void{$this->expectException(RuntimeException::class);try{$this->read(fn()=>$this->lease->assertNoMetadataWrite());}finally{self::assertFalse($this->gate->active);$this->lease->assertNoMetadataWrite();}}
 public function testReentrantMetadataUsesTheSameSourceFrame():void{self::assertSame(9,$this->read(fn()=>$this->read(function():int{self::assertTrue($this->gate->active);return 9;})));self::assertSame(1,$this->gate->frames);}
}
}
